heizungsmodernisierung_mit_jahresfoerderung <- function(kosten_wohnung=NULL, von_erhaltungspauschale_ausgenommene_kosten=NULL, kapitalzuschuesse=NULL, jaehrliche_zinsermaessigung=NULL, jaehrliche_laufende_foerderung=NULL, monatliche_restkappung=NULL, abzugsreihenfolge=NULL, methodennachweis=NULL) {
 k <- .geld(kosten_wohnung);e <- .geld(von_erhaltungspauschale_ausgenommene_kosten);z <- .geld(kapitalzuschuesse);zins <- .geld(jaehrliche_zinsermaessigung);laufend <- .geld(jaehrliche_laufende_foerderung);.text(methodennachweis,'methodennachweis')
 if(.vergleichen(e,k)>0||.vergleichen(z,k)>0) .fehler('kosten_und_foerderung','Ausnahmeanteil und Kapitalbeitrag jeweils h\u00f6chstens Kosten.')
 if(.vergleichen(.addieren(.addieren(z,zins),laufend),.bruch(0))<=0) .fehler('foerderung','Tats\u00e4chliche positive F\u00f6rderung erforderlich; ohne F\u00f6rderung559gesondert.')
 pausch <- .multiplizieren(.subtrahieren(k,e),.bruch(3,20));basis <- .subtrahieren(.subtrahieren(k,pausch),z);if(.vergleichen(basis,.bruch(0))<0)basis <- .bruch(0)
 jahr <- .multiplizieren(basis,.bruch(1,10))
 foerderung <- modernisierung_kappung_mit_laufenden_abzuegen(.bruchteile(jahr),jaehrliche_zinsermaessigung,jaehrliche_laufende_foerderung,monatliche_restkappung,abzugsreihenfolge,methodennachweis)$wert
 wert <- list(erhaltungspauschale=.bruchteile(pausch),kostenbasis=.bruchteile(basis),jahresbetrag_vor_jahresfoerderung=.bruchteile(jahr),foerderkappung=foerderung)
 eingaben <- list(kosten_wohnung=kosten_wohnung, von_erhaltungspauschale_ausgenommene_kosten=von_erhaltungspauschale_ausgenommene_kosten, kapitalzuschuesse=kapitalzuschuesse, jaehrliche_zinsermaessigung=jaehrliche_zinsermaessigung, jaehrliche_laufende_foerderung=jaehrliche_laufende_foerderung, monatliche_restkappung=monatliche_restkappung, abzugsreihenfolge=abzugsreihenfolge, methodennachweis=methodennachweis)
 ergebnis <- .ergebnis(wert,"EUR","BGB_HEIZUNGSMODERNISIERUNG_MIT_JAHRESFOERDERUNG",eingaben,list(list(operation="559e-Kostenbasis und10%-Jahresumlage mit ausdr\u00fccklich qualifizierter559aII-Jahresf\u00f6rderung/Kappungsreihenfolge verbinden.")),eingaben)
 ergebnis$hinweise <- list("Bedingte Heizungsrechnung nach559e:15%des nicht nach lokaler559eII2ausgenommenen Kostenanteils als Erhaltungspauschale, dann einmaliger Kapitalbeitrag, positive Kostenbasis*10%j\u00e4hrlich. Qualifizierte559aII-Zins-/laufende Jahresf\u00f6rderung mit bestehendem F\u00f6rderkappungskern ber\u00fccksichtigen. Die rechtliche \u00dcbertragung dieser Jahresabzugsmethode auf den konkreten559e-F\u00f6rderfall wird ausdr\u00fccklich vorausgesetzt, nicht als allgemein gekl\u00e4rt behauptet. Der Nennbetrag eines r\u00fcckzahlbaren Darlehens wird nicht ohne Rechtsgrund als verlorener Kapitalzuschuss behandelt. Mindestens eine tats\u00e4chliche ber\u00fccksichtigungsf\u00e4hige F\u00f6rderung erforderlich; ohne F\u00f6rderung ist559-Verfahren gesondert. Kein doppelter Abzug tats\u00e4chlicher Erhaltungskosten zus\u00e4tzlich zur Pauschale; keine automatische H\u00e4rte-/F\u00f6rderf\u00e4higkeitsentscheidung.")
 ergebnis
}
